function updateCron() {
            const m = document.getElementById('c-min').value || '*';
            const h = document.getElementById('c-hour').value || '*';
            const d = document.getElementById('c-day').value || '*';
            const mon = document.getElementById('c-month').value || '*';
            const w = document.getElementById('c-week').value || '*';
            const full = `${m} ${h} ${d} ${mon} ${w}`;
            document.getElementById('full-syntax').innerText = full;
            parseReadable(m, h, d, mon, w);
            generateTimeline();
        }
        function parseReadable(m, h, d, mon, w) {
            let desc = "Runs ";
            if (m === '*' && h === '*') desc += "every minute ";
            else if (m.startsWith('*/')) desc += `every ${m.split('/')[1]} minutes `;
            else if (m !== '*') desc += `at minute ${m} `;
            if (h.startsWith('*/')) desc += `every ${h.split('/')[1]} hours `;
            else if (h !== '*') desc += `of hour ${h} `;
            if (d !== '*') desc += `on day ${d} of the month `;
            if (mon !== '*') desc += `in month ${mon} `;
            if (w !== '*') desc += `on weekday ${w} `;
            if (m === '*' && h === '*' && d === '*' && mon === '*' && w === '*') {
                desc = "Every minute of every hour of every day.";
            }
            document.getElementById('readable-str').innerText = `“${desc.trim()}.”`;
        }
        function generateTimeline() {
            const list = document.getElementById('execution-list');
            list.innerHTML = '';
            const now = new Date();
            for (let i = 1; i <= 5; i++) {
                // Simplified simulation: increments based on 1st parameter for visual representation
                // A production version would use a proper CRON parser library like cron-parser
                const date = new Date(now.getTime() + i * 60000);
                const pill = document.createElement('div');
                pill.className = 'execution-pill';
                pill.innerHTML = `
                    <div class="flex-shrink-0 w-10 h-10 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center font-black">#${i}</div>
                    <div>
                        <div class="text-sm font-black text-slate-800">${date.toLocaleDateString()}</div>
                        <div class="text-xs text-slate-500 font-mono">${date.toLocaleTimeString()}</div>
                    </div>
                `;
                list.appendChild(pill);
            }
        }
        function setPreset(syntax) {
            const parts = syntax.split(' ');
            document.getElementById('c-min').value = parts[0];
            document.getElementById('c-hour').value = parts[1];
            document.getElementById('c-day').value = parts[2];
            document.getElementById('c-month').value = parts[3];
            document.getElementById('c-week').value = parts[4];
            updateCron();
        }
        // --- GLOBAL SCROLL LOGIC ---
        window.onload = updateCron;
